import {createSaveSlotStore,decodeSlot} from '../compatibility/save-slots.mjs';
import {stableJSON} from '../compatibility/codec.mjs';
import {CANDIDATE_ID} from '../economy/contract.mjs';
import {adoptPlacementPosition,validateWorldLocation} from './state.mjs';
export const WORLD_CANDIDATE_PREFIX='geoje.dev.world-candidate-v1.',WORLD_QA_PREFIX='geoje.dev.world-qa-v1.';
export function createWorldStore(storage,catalog,host,{qa=false}={}){const candidate=catalog.economyPolicy?.id===CANDIDATE_ID,prefix=candidate?WORLD_CANDIDATE_PREFIX:qa?WORLD_QA_PREFIX:'',scoped=prefix?{getItem:k=>storage.getItem(prefix+k),setItem:(k,v)=>storage.setItem(prefix+k,v),removeItem:k=>storage.removeItem(prefix+k)}:storage,store=createSaveSlotStore(scoped,{canonicalCatalog:catalog,allowCandidate:candidate});return {prefix,has:store.has,keys:store.keys,save(slot,s){if(!s.world)throw Error('World save required');validateWorldLocation(s,host);const raw=store.peek(slot);if(raw){const old=decodeSlot(raw,slot,{canonicalCatalog:catalog,allowCandidate:candidate});if(stableJSON(old.runtime)===stableJSON(s)){store.load(slot);return old}}return store.save(slot,s)},load(slot,{backup=false}={}){const s=store.loadSession(slot,{backup,legacyFallback:false})?.runtime;if(!s)return null;if(!s.world)throw Error('Existing non-world save retained; automatic conversion disabled');const adopted=adoptPlacementPosition(s,host);validateWorldLocation(adopted,host);return adopted}}}
